#!/usr/bin/env python3
"""报告语言。按使用人口：英语、中文、印地语、西班牙语、法语、阿拉伯语、孟加拉语、葡萄牙语、俄语、乌尔都语。

没传 --lang 时读 LC_ALL、LC_MESSAGES、LANG。识别不了就用中文，和原来的报告一致。
繁体中文目前用简体。引擎原文仍是中文；这里只翻译报告。对得上的句子会翻译，对不上的保留原文。
"""

from __future__ import annotations

import os
import re

LANGS = ("zh", "en", "hi", "es", "fr", "ar", "bn", "pt", "ru", "ur")
HTML_LANG = {
    "zh": "zh-CN", "en": "en", "hi": "hi", "es": "es", "fr": "fr",
    "ar": "ar", "bn": "bn", "pt": "pt", "ru": "ru", "ur": "ur",
}
RTL = {"ar", "ur"}
ALIASES = {
    "zh": "zh", "cmn": "zh", "chi": "zh",
    "en": "en", "eng": "en",
    "hi": "hi", "hin": "hi",
    "es": "es", "spa": "es",
    "fr": "fr", "fra": "fr", "fre": "fr",
    "ar": "ar", "ara": "ar",
    "bn": "bn", "ben": "bn",
    "pt": "pt", "por": "pt",
    "ru": "ru", "rus": "ru",
    "ur": "ur", "urd": "ur",
}


def P(*parts: str) -> dict[str, str]:
    if len(parts) != 10:
        raise RuntimeError(f"需要 10 种译文，得到 {len(parts)}：{parts[:1]}")
    return dict(zip(LANGS, parts))


def normalize(raw: str | None) -> str | None:
    if not raw:
        return None
    token = raw.strip().replace("-", "_").split(".")[0].lower()
    if not token or token in {"c", "posix"}:
        return None
    return ALIASES.get(token.split("_")[0])


def resolve(explicit: str | None) -> str:
    if explicit:
        lang = normalize(explicit)
        if not lang:
            raise ValueError(
                f"不认识的语言 {explicit}。可用：{' '.join(LANGS)}"
            )
        return lang
    for key in ("LC_ALL", "LC_MESSAGES", "LANG"):
        raw = os.environ.get(key)
        if raw is None or not raw.strip():
            continue
        lang = normalize(raw)
        if lang:
            return lang
        token = raw.strip().replace("-", "_").split(".")[0].lower()
        if token in {"c", "posix"}:
            return "zh"
    return "zh"


def t(lang: str, key: str, **kw) -> str:
    row = TEXT[key]
    text = row.get(lang) or row["zh"]
    return text.format(**kw) if kw else text


TEXT: dict[str, dict[str, str]] = {}


def put(key: str, *parts: str) -> None:
    TEXT[key] = P(*parts)


