def _format_match(lang: str, key: str, groups: tuple[str, ...]) -> str:
    names = "abcdefghij"
    return t(lang, key, **{names[i]: groups[i] for i in range(len(groups))})


def translate_phrase(text: str, lang: str) -> str:
    if not text or lang == "zh":
        return text
    moved = re.match(r"^(HTTP \d+)；从 (.+) 跳转到 (.+)，后续按 (.+) 检查(（.+）)?$", text)
    if moved:
        base = translate_phrase(moved.group(1), lang)
        tail = moved.group(5) or ""
        return t(lang, "pat.redirect").format(base=base, src=moved.group(2), dst=moved.group(3), origin=moved.group(4)) + tail
    for pattern, key in _PATTERNS:
        found = pattern.match(text)
        if found:
            return _format_match(lang, key, found.groups())
    row = PHRASE.get(text)
    if row:
        return row.get(lang) or text
    return text


