def localize_check(check: dict, lang: str) -> tuple[str, str, str]:
    cid = check.get("id") or ""
    title_key = "title." + cid
    title = t(lang, title_key) if title_key in TEXT else (check.get("title") or "")
    message = translate_phrase(check.get("message") or "", lang)
    fix = translate_phrase(check.get("fix") or "", lang)
    return title, message, fix


def gap(lang: str, text: str) -> str:
    if text == "红线未全部通过":
        return t(lang, "gap.redlines")
    found = re.match(r"^(D\d+) .+：(\d+) → (\d+)$", text)
    if not found:
        return text
    code, a, b = found.groups()
    return t(lang, "gap.dim", code=code, name=t(lang, "dim." + code), a=a, b=b)


def note(lang: str, text: str) -> str:
    missing = re.match(r"^(D\d+) 缺失，按 0 分计$", text)
    if missing:
        return t(lang, "note.missing", code=missing.group(1))
    bare = re.match(r"^(D\d+) 没有证据，按 0 分计$", text)
    if bare:
        return t(lang, "note.no_evidence", code=bare.group(1))
    return text
